import re
import os
import shutil
import errno
from datetime import datetime
from fnmatch import filter
from ta_tti_parser import ta_tti_parser  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.procedure.db_markers import add_tti_cells_stats
from taf.ul.sc.perf.util.logger import (log_info_to_console, log_function_status_to_console, log_debug_function_info)


class TtiResults(object):
    def __init__(self, traces, cell_id, direction):
        self.columns_filter = {
            'DL': [
                'Time',
                'ETtiTraceDlParCell_numUesFd',
                'EHarqParDl_ackNackDtxCw1',
                'EHarqParDl_ackNackDtxCw2',
                'ETtiTraceDlParCell_cellId',
                'ETtiTraceDlParUe_dataTakenDrb1',
                'ETtiTraceDlParUe_dataTakenDrb2',
                'ETtiTraceDlParUe_dataTakenDrb3',
                'ETtiTraceDlParUe_dataTakenDrb4',
                'ETtiTraceDlParUe_dataTakenDrb5',
                'ETtiTraceDlParUe_dataTakenDrb6',
                'ETtiTraceDlParUe_dataTakenDrb7',
                'ETtiTraceDlParUe_dataTakenDrb8',
                'ETtiTraceDlParUe_cRnti',
            ],
            'UL': [
                'Time',
                'ETtiTraceUlParCell_numUesFd',
                'EHarqParUl_ackNackDtxCw1',
                'ETtiTraceUlParCell_cellId',
                'EHarqParUl_dataRcvdLcg1',
                'EHarqParUl_dataRcvdLcg2',
                'EHarqParUl_dataRcvdLcg3',
                'ETtiTraceUlParUe_cRnti',
            ]
        }
        self.counter = {
            'current_ues_fd': 0,
            'current_count_tb': 0,
            'max_ues_fd1': 0,
            'max_tb1': 0,
            'max_ues_fd2': 0,
            'max_tb2': 0,
            'compare_time': '',
        }
        self.cell_id = cell_id
        self.direction = direction
        self.tti_columns = self._get_columns_values(traces, cell_id, direction)
        self.throughput = self._calculate_throughput()
        self.users_amount = self._count_users()
        self._parse_tti_values()

    @staticmethod
    def _get_column_values(traces, cell_id, field):
        return traces.cell(cell_id=cell_id).values_by_field(field, unique=False).result_list

    @staticmethod
    def _time_diff(start, stop):
        first = datetime.strptime(start, '%H:%M:%S:%f')
        last = datetime.strptime(stop, '%H:%M:%S:%f')
        diff = last - first
        return float(diff.seconds) + float(diff.microseconds) / 1000000

    @staticmethod
    def _lower_case_last_letter(word):
        return word[:-1] + word[-1].lower()

    def _get_columns_values(self, traces, cell_id, direction):
        tti_columns = {}
        for field in self.columns_filter[direction]:
            tti_columns[field] = self._get_column_values(traces, cell_id, field)
        return tti_columns

    def _calculate_throughput(self):
        pattern = '.*(Dl|Ul).*data'
        start_time = self.tti_columns['Time'][0]
        stop_time = self.tti_columns['Time'][-1]
        tti_trace_duration = self._time_diff(start_time, stop_time)
        throughput = 0
        for field in self.columns_filter[self.direction]:
            result = re.match(pattern, field)
            if field in self.tti_columns and result:
                throughput += sum([x for x in self.tti_columns[field] if x != '-'])
                # throughput += sum(map(lambda x: int(x) if x != '-' else 0, self.tti_columns[field]))
        throughput = round((float(throughput) * 8 / tti_trace_duration) / (1000 * 1000), 2)
        return throughput

    def _check_ack(self, index):
        column_dtx_cw1 = 'EHarqPar{}_ackNackDtxCw1'.format(self._lower_case_last_letter(self.direction))
        column_dtx_cw2 = 'EHarqPar{}_ackNackDtxCw2'.format(self._lower_case_last_letter(self.direction))
        ack_nack_1 = 0
        ack_nack_2 = 0
        if self.tti_columns[column_dtx_cw1][index] == ('ACK' or 'NACK'):
            ack_nack_1 = 1
        if column_dtx_cw2 in self.tti_columns.keys():
            if self.tti_columns[column_dtx_cw2][index] == ('ACK' or 'NACK'):
                ack_nack_2 = 1
        return ack_nack_1, ack_nack_2

    def _parse_tti_values(self):
        column_num_ues_fd = 'ETtiTrace{}ParCell_numUesFd'.format(self._lower_case_last_letter(self.direction))
        for index, num_ues_fd in enumerate(self.tti_columns[column_num_ues_fd]):
            ack_nack_1, ack_nack_2 = self._check_ack(index)
            tti_time = self.tti_columns['Time'][index]
            if tti_time != self.counter['compare_time']:
                if self.counter['current_count_tb'] > self.counter['max_tb1']:
                    self.counter['max_tb1'] = self.counter['current_count_tb']
                    self.counter['max_ues_fd1'] = self.counter['current_ues_fd']
                if self.counter['current_ues_fd'] > self.counter['max_ues_fd2']:
                    self.counter['max_ues_fd2'] = self.counter['current_ues_fd']
                    self.counter['max_tb2'] = self.counter['current_count_tb']
                self.counter['current_ues_fd'] = 0
                self.counter['current_count_tb'] = 0
            self.counter['current_count_tb'] += (ack_nack_1 + ack_nack_2)
            self.counter['compare_time'] = tti_time
            self.counter['current_ues_fd'] = int(num_ues_fd)

    def _count_users(self):
        column_crnti = 'ETtiTrace{}ParUe_cRnti'.format(self._lower_case_last_letter(self.direction))
        users = 0
        for crnti in set(self.tti_columns[column_crnti]):
            if 'PDCCH' not in crnti:
                if crnti != '-' and 'blocked' not in crnti:
                    users += 1
        return users

    def __str__(self):
        tti_printout_data = "\n"
        tti_printout_data += "TTI: Cell {}{} throughput: {:.2f} Mbps, users amount: {}\n".format(self.cell_id,
                                                                                                 self.direction,
                                                                                                 self.throughput,
                                                                                                 self.users_amount)
        tti_printout_data += "TTI: Cell {}{} Max TB amount: {}, UEs in that tti: {},\n".format(self.cell_id,
                                                                                               self.direction,
                                                                                               self.counter['max_tb1'],
                                                                                               self.counter[
                                                                                                   'max_ues_fd1'])
        tti_printout_data += "TTI: Cell {}{} Max UEs per TTI: {}, TBs in that tti: {}\n".format(self.cell_id,
                                                                                                self.direction,
                                                                                                self.counter[
                                                                                                    'max_ues_fd2'],
                                                                                                self.counter['max_tb2'])
        return tti_printout_data


class TtiCollector(object):
    def __init__(self, bts_name, cells_names, tti_collection_interval, bts_id=1, alias='alias', output_dir=None):
        self.parser = ta_tti_parser()
        self.alias = alias
        self.bts_id = bts_id
        self.bts_name = bts_name
        self.cells_names = cells_names
        self.tti_collection_interval = tti_collection_interval
        self.output_dir = output_dir
        self.all_statistics = {}

    @staticmethod
    def _get_cell_id(cell_name):
        cell_pattern = r'(\s+)?LNCEL-(\d+)'
        cell_id = None
        m = re.match(cell_pattern, cell_name)
        if m:
            cell_id = int(m.group(2))
        return cell_id

    @log_function_status_to_console(msg='Collecting TTI traces', log_hierarchy=3)
    @log_debug_function_info()
    def collect_tti_traces(self):
        self.parser.create_tti_alias(self.alias, enb_id=self.bts_id, lncels=','.join(self.cells_names))
        self.parser.start_tti_trace_for_aliases(self.alias)
        MolerTest.sleep(self.tti_collection_interval)
        self.parser.stop_tti_trace_for_aliases(self.alias)

    @log_function_status_to_console(msg='Parsing TTI traces', log_hierarchy=3)
    @log_debug_function_info()
    def parse_tti_traces(self):
        directions = ['DL', 'UL']
        all_traces = {}
        for direction in directions:
            all_traces[direction] = self.parser.get_trace(self.alias, direction)

        for cell_name in self.cells_names:
            self.all_statistics[cell_name] = {}
            cell_id = self._get_cell_id(cell_name)
            for direction in directions:
                self.all_statistics[cell_name][direction] = TtiResults(all_traces[direction], cell_id, direction)
                log_info_to_console(msg=self.all_statistics[cell_name][direction], log_hierarchy=3)

    def get_all_statistics(self):
        return self.all_statistics

    def trigger_tti_collection(self, sample_id=1, add_tti_stats=False):
        self.collect_tti_traces()
        self.parse_tti_traces()
        all_stats = self.get_all_statistics()
        if add_tti_stats:
            add_tti_cells_stats(self.bts_name, all_stats, sample_id=sample_id)
        if self.output_dir:
            destination_dir = os.path.join(self.output_dir, self.alias)
            move_tti_files(log_dir=self.output_dir, destination_dir=destination_dir)


def get_tti_files_from_dir(directory):
    tti_files = filter(os.listdir(directory), 'tti_trace*')
    tti_files += filter(os.listdir(directory), 'merged_*')
    return tti_files


def remove_old_tti_files(log_dir, debug_tti_dir=None, dir_pattern=None):
    files_to_delete = get_tti_files_from_dir(directory=log_dir)
    if files_to_delete:
        for file in files_to_delete:
            os.remove(os.path.join(log_dir, file))
    if debug_tti_dir and os.path.isdir(debug_tti_dir):
        shutil.rmtree(debug_tti_dir)
    if dir_pattern:
        remove_log_directories(dir_pattern, log_dir)


def remove_log_directories(dir_pattern, log_dir):
    dirs_to_delete = filter(os.listdir(log_dir), dir_pattern)
    for dir_to_delete in dirs_to_delete:
        path_dir = os.path.join(log_dir, dir_to_delete)
        if os.path.isdir(path_dir):
            shutil.rmtree(path_dir)


def move_tti_files(log_dir, destination_dir):
    try:
        os.makedirs(destination_dir)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise

    files_to_move = get_tti_files_from_dir(directory=log_dir)

    if files_to_move:
        for file in files_to_move:
            shutil.move(os.path.join(log_dir, file), destination_dir)


def move_and_zip_tti_directories(log_dir, destination_dir, dir_pattern):
    dirs_to_move = filter(os.listdir(log_dir), dir_pattern)
    for dir_to_move in dirs_to_move:
        source_path = os.path.join(log_dir, dir_to_move)
        if os.path.isdir(source_path):
            destination_path = os.path.join(destination_dir, dir_to_move)
            shutil.move(source_path, destination_path)
            shutil.make_archive(destination_path, 'zip', destination_path)
            shutil.rmtree(destination_path)
    ta_tti_parser_file = 'ta_tti_parser.log'
    shutil.move(os.path.join(log_dir, ta_tti_parser_file), os.path.join(destination_dir, ta_tti_parser_file))
